property.value:
let $keyword := function($e) {
      exists($e/self::StringLiteral[matches(string(@ConstValue),
        '\\b(\(\?:|\()?(abstract|async|await|case|catch|class|const|def|elif|enum|export|extends|final|finally|fun|func|function|implements|import|instanceof|interface|package|private|protected|public|require|return|static|struct|switch|synchronized|throw|throws|try|typeof|yield)(\\b|\\s|\\\(|[|)])')])
    },
    $sourceText := function($e) {
      exists($e/self::VariableAccess[@Name = ('source', 'sourceText', 'sourceCode')])
    },
    $keywordPattern := function($e) {
      exists($e/self::MethodCall[@MethodName = 'compile'][*[1]/self::TypeExpression/ClassType[@SimpleName = 'Pattern']]
               [$keyword(ArgumentList/*[1])])
    },
    $skipsCommentsIn := function($m) {
      exists($m//MethodCall[matches(@MethodName, '(strip|mask|blank)\w*(comment|string|literal)|removeComments|tokeni[sz]e|^lex', 'i') or matches(@MethodName, '[a-z]Lex')])
    },
    $maskedParameter := function($e) {
      let $name := $e/self::VariableAccess/@Name,
          $method := $e/ancestor::MethodDeclaration[1]
      return exists($name) and exists($method[@Visibility = 'private'])
        and exists($method/FormalParameters/FormalParameter/VariableId[@Name = $name])
        and (let $index := count($method/FormalParameters/FormalParameter[VariableId/@Name = $name]/preceding-sibling::FormalParameter) + 1,
                 $calls := $method/ancestor::ClassDeclaration[1]//MethodCall[@MethodName = $method/@Name]
             return exists($calls) and (every $call in $calls satisfies
               exists($call/ArgumentList/*[$index]/self::MethodCall[matches(@MethodName, '^(strip|mask|blank|tokeni[sz]e|lex)', 'i')])))
    },
    $maskedLocal := function($e) {
      let $name := $e/self::VariableAccess/@Name
      return exists($name) and exists($e/ancestor::MethodDeclaration[1]//LocalVariableDeclaration/VariableDeclarator[@Name = $name]
               /*[last()]/self::MethodCall[matches(@MethodName, '^(strip|mask|blank)', 'i')])
    }
return
(//MethodCall[@MethodName = ('matches', 'replaceAll', 'replaceFirst', 'split')][ArgumentList/@Size >= 1]
   [$sourceText(*[1])][$keyword(ArgumentList/*[1])][not($maskedParameter(*[1]))][not($maskedLocal(*[1]))]
 | //MethodCall[@MethodName = 'matcher'][ArgumentList/@Size = 1][$sourceText(ArgumentList/*[1])]
   [not($maskedParameter(ArgumentList/*[1]))][not($maskedLocal(ArgumentList/*[1]))]
   [$keywordPattern(*[1])
    or (let $held := *[1]/self::VariableAccess/@Name
        return exists($held) and exists(ancestor::ClassDeclaration[1]//VariableDeclarator[@Name = $held]/*[last()]
                                          [$keywordPattern(.)]))])
  [not($skipsCommentsIn(ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression or self::Initializer][1]))]
